-- Phase 2 (docs/phase-2/acceptance-criteria.md, decisions 004 and 005):
--   1. home_services: the seven priced services move from catalog.ts into a table
--      the admin edits (Q7). The tap questions stay in code. Seeded from the catalog
--      by scripts/seed-home-services.ts so the seed equals the code on day one.
--   2. blog_posts: guarded columns for Claude-written articles (Q9, Q10). The table
--      was created in the dashboard and has no migration of its own, so every
--      column is added only if the table exists, the way projects is guarded in
--      20261029000000_home_services.sql.
--   3. experiments: the Phase 1 CTA test generalised (decision 005, slice H).
--      Prices are never a variant payload; the API enforces it and a test pins it.
-- RLS is on with no policies on every new table: server code reads and writes
-- with the service key, admin UI goes through /api/admin/*.

-- 1. home_services --------------------------------------------------------

CREATE TABLE IF NOT EXISTS public.home_services (
  slug text PRIMARY KEY,
  sort integer NOT NULL DEFAULT 0,
  active boolean NOT NULL DEFAULT true,
  trade text NOT NULL,
  icon text NOT NULL,
  image text,
  starting_price_cents integer NOT NULL CHECK (starting_price_cents > 0),
  price_display_en text NOT NULL,
  price_display_es text NOT NULL,
  price_unit_en text NOT NULL,
  price_unit_es text NOT NULL,
  price_note_en text,
  price_note_es text,
  minimum_cents integer CHECK (minimum_cents IS NULL OR minimum_cents > 0),
  name_en text NOT NULL,
  name_es text NOT NULL,
  description_en text NOT NULL,
  description_es text NOT NULL,
  included_en jsonb NOT NULL DEFAULT '[]'::jsonb,
  included_es jsonb NOT NULL DEFAULT '[]'::jsonb,
  raises_en jsonb NOT NULL DEFAULT '[]'::jsonb,
  raises_es jsonb NOT NULL DEFAULT '[]'::jsonb,
  seo_title_en text NOT NULL,
  seo_title_es text NOT NULL,
  seo_description_en text NOT NULL,
  seo_description_es text NOT NULL,
  seo_keywords jsonb NOT NULL DEFAULT '[]'::jsonb,
  faq jsonb NOT NULL DEFAULT '[]'::jsonb,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid
);
ALTER TABLE public.home_services ENABLE ROW LEVEL SECURITY;

INSERT INTO public.home_services (slug, sort, active, trade, icon, image, starting_price_cents, price_display_en, price_display_es, price_unit_en, price_unit_es, price_note_en, price_note_es, minimum_cents, name_en, name_es, description_en, description_es, included_en, included_es, raises_en, raises_es, seo_title_en, seo_title_es, seo_description_en, seo_description_es, seo_keywords, faq) VALUES
  ('cabinet-repainting', 1, true, 'cabinet_painting', 'paint-roller', null, 209500, '$2,095', '$2,095', 'per kitchen, up to 25 doors and drawers', 'por cocina, hasta 25 puertas y cajones', null, null, null, 'Cabinet repainting', 'Repintado de gabinetes', 'Clean, sand, prime and spray paint existing cabinet doors and boxes. Price covers a standard kitchen up to 25 doors and drawers.', 'Limpiamos, lijamos, imprimamos y pintamos con pistola las puertas y cajas de gabinetes existentes. El precio cubre una cocina estándar de hasta 25 puertas y cajones.', '["Degrease, sand and prime every door, drawer front and box face","Two coats of cabinet enamel, sprayed","Hardware removed and reinstalled","Masking and cleanup"]'::jsonb, '["Desengrasar, lijar e imprimar cada puerta, frente de cajón y cara de caja","Dos capas de esmalte para gabinetes, con pistola","Herrajes retirados y reinstalados","Protección de superficies y limpieza"]'::jsonb, '["More than 25 doors and drawers","A color change from dark to light","Islands, glass doors or heavy damage"]'::jsonb, '["Más de 25 puertas y cajones","Cambio de color de oscuro a claro","Islas, puertas de vidrio o daños importantes"]'::jsonb, 'Cabinet Painting in Essex, Morris, Bergen & Union NJ, $2,095', 'Pintar gabinetes en Essex, Morris, Bergen y Union, $2,095', 'Cabinet repainting costs from $2,095 in Essex, Morris, Bergen and Union NJ. Sprayed enamel, two coats, firm quote from your photos the same day.', 'Repintado de gabinetes desde $2,095 en Essex, Morris, Bergen y Union NJ. Esmalte con pistola, dos capas y cotización firme con sus fotos el mismo día.', '["cabinet painting NJ","how much does cabinet painting cost in NJ","cabinet painting near me","cabinet refinishing Essex County","kitchen cabinet painting Morris County","cabinet painters Bergen County","cabinet painting Union County"]'::jsonb, '[{"q":{"en":"How much does cabinet repainting cost in NJ?","es":"¿Cuánto cuesta el repintado de gabinetes en NJ?"},"a":{"en":"From $2,095 for a standard kitchen of up to 25 doors and drawers: degreased, sanded, primed and sprayed with two coats of cabinet enamel. More doors, an island or a dark-to-light color change add to it, and you get the firm price from your photos before anything starts.","es":"Desde $2,095 por una cocina estándar de hasta 25 puertas y cajones: desengrasada, lijada, imprimada y pintada con pistola con dos capas de esmalte. Más puertas, una isla o un cambio de oscuro a claro suben el precio, y recibe el precio firme con sus fotos antes de empezar."}},{"q":{"en":"How long does it take?","es":"¿Cuánto tarda?"},"a":{"en":"Three to five working days for most kitchens. The doors are sprayed off site, so your kitchen stays usable in between.","es":"De tres a cinco días hábiles en la mayoría de las cocinas. Las puertas se pintan fuera del sitio, así que la cocina sigue siendo usable mientras tanto."}},{"q":{"en":"Can I change the color?","es":"¿Puedo cambiar el color?"},"a":{"en":"Yes. Dark to light needs extra primer coats, which is one of the things that moves the price.","es":"Sí. De oscuro a claro requiere capas extra de imprimación, y eso es parte de lo que mueve el precio."}},{"q":{"en":"Can I add other services to the same request?","es":"¿Puedo agregar otros servicios a la misma solicitud?"},"a":{"en":"Yes. Tick drywall patching or a deep clean, or anything else on the list, and send one request. You get one firm price, one schedule and one point of contact; the crews come in order while you sit back.","es":"Sí. Marque reparación de drywall o una limpieza profunda, o cualquier otro servicio de la lista, y envíe una sola solicitud. Recibe un solo precio firme, una sola agenda y un solo contacto; los equipos llegan en orden mientras usted se relaja."}}]'::jsonb),
  ('hvac-cleaning', 2, true, 'hvac', 'fan', null, 29900, '$299', '$299', 'per system', 'por sistema', null, null, null, 'HVAC cleaning', 'Limpieza de HVAC', 'Coil, blower and drain line cleaning plus filter change. One system; add systems at checkout.', 'Limpieza de serpentín, ventilador y línea de drenaje, más cambio de filtro. Un sistema; agregue sistemas al solicitar.', '["Evaporator and condenser coil cleaning","Blower and drain line cleared","Standard filter replaced","System run test"]'::jsonb, '["Limpieza de serpentín evaporador y condensador","Ventilador y línea de drenaje despejados","Filtro estándar reemplazado","Prueba de funcionamiento del sistema"]'::jsonb, '["Each additional system","Rooftop or attic units with difficult access","Repairs found during the service (quoted separately)"]'::jsonb, '["Cada sistema adicional","Unidades en techo o ático de difícil acceso","Reparaciones encontradas durante el servicio (se cotizan aparte)"]'::jsonb, 'HVAC Cleaning in Essex, Morris, Bergen & Union NJ from $299', 'Limpieza de HVAC en Essex, Morris, Bergen y Union desde $299', 'HVAC cleaning costs from $299 per system in Essex, Morris, Bergen and Union NJ: coil, blower and drain line cleaned, filter changed. Firm price.', 'Limpieza de HVAC desde $299 por sistema en Essex, Morris, Bergen y Union NJ: serpentín, ventilador y drenaje limpios, filtro nuevo. Precio firme.', '["HVAC cleaning NJ","how much does HVAC cleaning cost","HVAC cleaning near me","AC coil cleaning Essex County","furnace cleaning Morris County","HVAC tune up Bergen County","HVAC cleaning Union County"]'::jsonb, '[{"q":{"en":"How much does HVAC cleaning cost in NJ?","es":"¿Cuánto cuesta la limpieza de HVAC en NJ?"},"a":{"en":"From $299 per system: the evaporator coil, blower and condensate drain line cleaned, a new filter fitted and the system checked. A second system or a heavily clogged coil adds to it, and the price is firm before the visit.","es":"Desde $299 por sistema: serpentín, ventilador y línea de drenaje limpios, filtro nuevo y revisión del sistema. Un segundo sistema o un serpentín muy obstruido suben el precio, y el precio es firme antes de la visita."}},{"q":{"en":"Is this a repair visit?","es":"¿Es una visita de reparación?"},"a":{"en":"No. It is a cleaning and tune. Anything that needs parts is quoted separately before any work.","es":"No. Es limpieza y ajuste. Cualquier pieza necesaria se cotiza aparte antes de hacer el trabajo."}},{"q":{"en":"How long does it take?","es":"¿Cuánto tarda?"},"a":{"en":"About two hours per system. You do not need to stay home once the tech is in.","es":"Unas dos horas por sistema. No necesita quedarse en casa una vez que el técnico entra."}},{"q":{"en":"Can I add other services to the same request?","es":"¿Puedo agregar otros servicios a la misma solicitud?"},"a":{"en":"Yes. Tick duct cleaning or gutter cleaning, or anything else on the list, and send one request. You get one firm price, one schedule and one point of contact; the crews come in order while you sit back.","es":"Sí. Marque limpieza de ductos o de canaletas, o cualquier otro servicio de la lista, y envíe una sola solicitud. Recibe un solo precio firme, una sola agenda y un solo contacto; los equipos llegan en orden mientras usted se relaja."}}]'::jsonb),
  ('duct-and-vent-cleaning', 3, true, 'duct_cleaning', 'wind', null, 44900, '$449', '$449', 'up to 10 vents', 'hasta 10 rejillas', null, null, null, 'Duct and vent cleaning', 'Limpieza de ductos y rejillas', 'Supply and return ducts vacuumed and sanitized. Additional vents priced per vent.', 'Ductos de suministro y retorno aspirados y desinfectados. Rejillas adicionales con precio por rejilla.', '["Negative-pressure vacuuming of supply and return runs","Vent covers removed, cleaned and refitted","Sanitizing fog"]'::jsonb, '["Aspirado a presión negativa de ductos de suministro y retorno","Rejillas retiradas, limpiadas y reinstaladas","Desinfección por nebulización"]'::jsonb, '["More than 10 vents","Dryer vent or furnace cleaning added","Heavy debris, pet hair or renovation dust"]'::jsonb, '["Más de 10 rejillas","Limpieza de ducto de secadora o caldera","Mucho polvo, pelo de mascotas o polvo de obra"]'::jsonb, 'Air Duct Cleaning in Essex, Morris, Bergen & Union from $449', 'Limpieza de ductos: Essex, Morris, Bergen y Union, $449', 'Air duct cleaning costs from $449 for up to 10 vents in Essex, Morris, Bergen and Union NJ. Vacuumed and sanitized in one visit, firm price from your photos.', 'Limpieza de ductos desde $449 por hasta 10 rejillas en Essex, Morris, Bergen y Union NJ. Aspirado y desinfectado en una visita, precio firme con sus fotos.', '["duct cleaning NJ","how much does duct cleaning cost","air duct cleaning near me","air duct cleaning Essex County","vent cleaning Morris County","duct cleaning Bergen County","air duct cleaning Union County"]'::jsonb, '[{"q":{"en":"How much does air duct cleaning cost in NJ?","es":"¿Cuánto cuesta la limpieza de ductos en NJ?"},"a":{"en":"From $449 for up to 10 vents: supply and return ducts vacuumed with negative air, registers washed and the system sanitized. Extra vents and a second system add to it, and you get the firm price from your photos.","es":"Desde $449 por hasta 10 rejillas: ductos de suministro y retorno aspirados con presión negativa, rejillas lavadas y sistema desinfectado. Rejillas extra o un segundo sistema suben el precio, y recibe el precio firme con sus fotos."}},{"q":{"en":"How often should ducts be cleaned?","es":"¿Cada cuánto se limpian los ductos?"},"a":{"en":"Every three to five years for most homes, sooner after a renovation or with pets.","es":"Cada tres a cinco años en la mayoría de las casas; antes si hubo obra o hay mascotas."}},{"q":{"en":"How long does it take?","es":"¿Cuánto tarda?"},"a":{"en":"Two to four hours for a typical home, done in one visit.","es":"De dos a cuatro horas en una casa típica, en una sola visita."}},{"q":{"en":"Can I add other services to the same request?","es":"¿Puedo agregar otros servicios a la misma solicitud?"},"a":{"en":"Yes. Tick HVAC cleaning or a home cleaning, or anything else on the list, and send one request. You get one firm price, one schedule and one point of contact; the crews come in order while you sit back.","es":"Sí. Marque limpieza de HVAC o limpieza de casa, o cualquier otro servicio de la lista, y envíe una sola solicitud. Recibe un solo precio firme, una sola agenda y un solo contacto; los equipos llegan en orden mientras usted se relaja."}}]'::jsonb),
  ('home-cleaning', 4, true, 'home_cleaning', 'sparkles', null, 25900, '$259', '$259', 'up to 2 bed, 1 bath', 'hasta 2 recámaras, 1 baño', null, null, null, 'Home cleaning', 'Limpieza de casa', 'Full standard clean: kitchen, baths, floors, dusting. Larger homes and deep cleans quoted.', 'Limpieza estándar completa: cocina, baños, pisos y polvo. Casas más grandes y limpiezas profundas se cotizan.', '["Kitchen surfaces, appliance exteriors and sink","Bathrooms scrubbed and sanitized","Floors vacuumed and mopped, surfaces dusted"]'::jsonb, '["Superficies de cocina, exterior de electrodomésticos y fregadero","Baños tallados y desinfectados","Pisos aspirados y trapeados, superficies sin polvo"]'::jsonb, '["Each extra bedroom or bathroom","Deep clean, move-out clean or inside appliances","Recurring visits are priced lower per visit"]'::jsonb, '["Cada recámara o baño adicional","Limpieza profunda, de mudanza o interior de electrodomésticos","Las visitas recurrentes tienen menor precio por visita"]'::jsonb, 'Home Cleaning in Essex, Morris, Bergen & Union NJ from $259', 'Limpieza de casa en Essex, Morris, Bergen y Union desde $259', 'House cleaning costs from $259 for up to 2 bedrooms and 1 bath in Essex, Morris, Bergen and Union NJ. Vetted crews, firm price up front, one-time or recurring.', 'Limpieza de casa desde $259 para hasta 2 recámaras y 1 baño en Essex, Morris, Bergen y Union NJ. Equipos verificados, precio firme, una vez o recurrente.', '["house cleaning NJ","how much does house cleaning cost in NJ","house cleaning near me","home cleaning Essex County","cleaning service Morris County","house cleaners Bergen County","house cleaning Union County"]'::jsonb, '[{"q":{"en":"How much does home cleaning cost in NJ?","es":"¿Cuánto cuesta la limpieza de casa en NJ?"},"a":{"en":"From $259 for a standard clean of up to two bedrooms and one bath: kitchen, baths, floors, surfaces and dusting. More rooms, a deep clean or a move-out clean add to it, and recurring visits are priced lower per visit.","es":"Desde $259 por una limpieza estándar de hasta dos recámaras y un baño: cocina, baños, pisos, superficies y polvo. Más cuartos, una limpieza profunda o de mudanza suben el precio, y las visitas recurrentes cuestan menos por visita."}},{"q":{"en":"Do I need to be home?","es":"¿Tengo que estar en casa?"},"a":{"en":"No. Many clients leave a key or lockbox code; the crew sends photos when done.","es":"No. Muchos clientes dejan una llave o código; el equipo envía fotos al terminar."}},{"q":{"en":"How soon can you come?","es":"¿Qué tan pronto pueden venir?"},"a":{"en":"Usually within the week. Tell us the day you want in the request and we confirm by text.","es":"Normalmente dentro de la misma semana. Indique el día que quiere en la solicitud y confirmamos por texto."}},{"q":{"en":"Can I add other services to the same request?","es":"¿Puedo agregar otros servicios a la misma solicitud?"},"a":{"en":"Yes. Tick gutter cleaning or drywall patching, or anything else on the list, and send one request. You get one firm price, one schedule and one point of contact; the crews come in order while you sit back.","es":"Sí. Marque limpieza de canaletas o reparación de drywall, o cualquier otro servicio de la lista, y envíe una sola solicitud. Recibe un solo precio firme, una sola agenda y un solo contacto; los equipos llegan en orden mientras usted se relaja."}}]'::jsonb),
  ('exterior-painting', 5, true, 'exterior_painting', 'house', null, 295, '$2.95 / sq ft', '$2.95 / pie²', '$3,600 minimum', 'mínimo $3,600', null, null, 360000, 'Exterior painting', 'Pintura exterior', 'Power wash, scrape, prime and two coats on siding and trim. Price from photos and square footage.', 'Lavado a presión, raspado, imprimación y dos capas en revestimiento y molduras. Precio según fotos y pies cuadrados.', '["Power wash and scrape loose paint","Spot prime bare wood, caulk gaps","Two coats of exterior paint on siding and trim"]'::jsonb, '["Lavado a presión y raspado de pintura suelta","Imprimación de madera expuesta y sellado de juntas","Dos capas de pintura exterior en revestimiento y molduras"]'::jsonb, '["Three stories or steep access","Wood rot, heavy peeling or lead-safe prep","Doors, shutters, decks and railings added"]'::jsonb, '["Tres pisos o acceso difícil","Madera podrida, mucha descascaración o preparación segura con plomo","Puertas, contraventanas, terrazas y barandas"]'::jsonb, 'Exterior Painting $2.95/sq ft: Essex, Morris, Bergen & Union', 'Pintura exterior: Essex, Morris, Bergen y Union, $2.95/pie²', 'Exterior painting costs $2.95 per sq ft, $3,600 minimum, in Essex, Morris, Bergen and Union NJ. Power wash, prime, two coats, firm quote from photos.', 'Pintura exterior a $2.95 por pie², mínimo $3,600, en Essex, Morris, Bergen y Union NJ. Lavado a presión, imprimación y dos capas, precio firme con fotos.', '["exterior painting NJ","how much does exterior painting cost in NJ","exterior painters near me","house painters Essex County","exterior painters Morris County","exterior painting Bergen County","exterior painting Union County"]'::jsonb, '[{"q":{"en":"How much does exterior painting cost in NJ?","es":"¿Cuánto cuesta la pintura exterior en NJ?"},"a":{"en":"$2.95 per square foot of painted wall, with a $3,600 job minimum: power wash, scrape and prime bare spots, two coats. Trim, doors and three-story work add to it, and the price is firm before a brush touches the house.","es":"$2.95 por pie cuadrado de pared pintada, con un mínimo de $3,600 por trabajo: lavado a presión, raspado e imprimación de zonas desnudas y dos capas. Molduras, puertas y tres pisos suben el precio, y el precio es firme antes de empezar."}},{"q":{"en":"How is square footage measured?","es":"¿Cómo se mide el área?"},"a":{"en":"Painted wall surface, not floor area. We confirm it from your photos and a quick site visit for larger homes.","es":"Superficie de pared pintada, no área de piso. La confirmamos con sus fotos y una visita rápida en casas grandes."}},{"q":{"en":"When is painting season?","es":"¿Cuándo es la temporada de pintura?"},"a":{"en":"April to October in North Jersey, when nights stay above 50°F. Book early; crews fill up by May.","es":"De abril a octubre en el norte de Nueva Jersey, cuando las noches se mantienen arriba de 50°F. Reserve temprano; los equipos se llenan en mayo."}},{"q":{"en":"Can I add other services to the same request?","es":"¿Puedo agregar otros servicios a la misma solicitud?"},"a":{"en":"Yes. Tick gutter cleaning or cabinet repainting, or anything else on the list, and send one request. You get one firm price, one schedule and one point of contact; the crews come in order while you sit back.","es":"Sí. Marque limpieza de canaletas o repintado de gabinetes, o cualquier otro servicio de la lista, y envíe una sola solicitud. Recibe un solo precio firme, una sola agenda y un solo contacto; los equipos llegan en orden mientras usted se relaja."}}]'::jsonb),
  ('gutter-cleaning', 6, true, 'gutter_cleaning', 'cloud-rain', null, 27900, '$279', '$279', 'single story', 'un piso', 'Two story from $349', 'Dos pisos desde $349', null, 'Gutter cleaning', 'Limpieza de canaletas', 'Clear gutters and downspouts, bag debris, flush and check for leaks.', 'Despejamos canaletas y bajantes, embolsamos los desechos, enjuagamos y revisamos fugas.', '["All gutters cleared by hand and flushed","Downspouts tested for flow","Debris bagged and removed","Photo report of any leak or loose hanger"]'::jsonb, '["Todas las canaletas limpiadas a mano y enjuagadas","Bajantes probados","Desechos embolsados y retirados","Reporte con fotos de fugas o soportes sueltos"]'::jsonb, '["Two or three stories","Gutter guards that must be removed and refitted","Repairs, resealing or new hangers"]'::jsonb, '["Dos o tres pisos","Protectores que deban retirarse y reinstalarse","Reparaciones, resellado o soportes nuevos"]'::jsonb, 'Gutter Cleaning in Essex, Morris, Bergen & Union from $279', 'Limpieza de canaletas en Essex, Morris, Bergen y Union, $279', 'Gutter cleaning costs from $279 single story, $349 two story, in Essex, Morris, Bergen and Union NJ. Cleared, flushed, checked and photographed, firm price.', 'Limpieza de canaletas desde $279 un piso, $349 dos pisos, en Essex, Morris, Bergen y Union NJ. Despejadas, enjuagadas, revisadas y con fotos, precio firme.', '["gutter cleaning NJ","how much does gutter cleaning cost","gutter cleaning near me","gutter cleaning Essex County","gutter cleaning Morris County","gutter cleaning Bergen County","gutter cleaning Union County"]'::jsonb, '[{"q":{"en":"How much does gutter cleaning cost in NJ?","es":"¿Cuánto cuesta la limpieza de canaletas en NJ?"},"a":{"en":"From $279 for a single-story home and $349 for two stories: every gutter cleared by hand, downspouts flushed, leaks and loose hangers noted with photos. Three stories, gutter guards and very long runs add to it, and the price is firm before the visit.","es":"Desde $279 en una casa de un piso y $349 en dos pisos: cada canaleta limpiada a mano, bajantes enjuagados, fugas y soportes sueltos anotados con fotos. Tres pisos, protectores de canaleta y tramos muy largos suben el precio, y el precio es firme antes de la visita."}},{"q":{"en":"When is the best time?","es":"¿Cuál es la mejor época?"},"a":{"en":"Late fall after the leaves drop and again in spring. Before a storm is the second best time.","es":"Fines de otoño cuando caen las hojas y otra vez en primavera. Antes de una tormenta es la segunda mejor opción."}},{"q":{"en":"Do I need to be home?","es":"¿Tengo que estar en casa?"},"a":{"en":"No. The crew works outside, bags the debris and texts you before-and-after photos when done.","es":"No. El equipo trabaja afuera, embolsa los desechos y le envía fotos del antes y después al terminar."}},{"q":{"en":"Can I add other services to the same request?","es":"¿Puedo agregar otros servicios a la misma solicitud?"},"a":{"en":"Yes. Tick exterior painting or HVAC cleaning, or anything else on the list, and send one request. You get one firm price, one schedule and one point of contact; the crews come in order while you sit back.","es":"Sí. Marque pintura exterior o limpieza de HVAC, o cualquier otro servicio de la lista, y envíe una sola solicitud. Recibe un solo precio firme, una sola agenda y un solo contacto; los equipos llegan en orden mientras usted se relaja."}}]'::jsonb),
  ('drywall-patching', 7, true, 'drywall', 'hammer', null, 34900, '$349', '$349', 'first patch up to 6 in, primed and painted', 'primer parche de hasta 6 pulg, imprimado y pintado', null, null, null, 'Drywall patching', 'Reparación de drywall', 'Patch, tape, mud, sand, prime and paint to blend. Additional patches priced each.', 'Parchamos, encintamos, aplicamos pasta, lijamos, imprimamos y pintamos para igualar. Parches adicionales con precio por unidad.', '["One patch up to 6 inches, taped and finished","Sanded smooth, primed and painted to blend","Texture matched where needed"]'::jsonb, '["Un parche de hasta 6 pulgadas, encintado y terminado","Lijado, imprimado y pintado para igualar","Textura igualada cuando se requiera"]'::jsonb, '["Each additional patch","Patches larger than 6 inches or on ceilings","Color matching when no leftover paint is on hand"]'::jsonb, '["Cada parche adicional","Parches mayores de 6 pulgadas o en techos","Igualar el color cuando no hay pintura sobrante"]'::jsonb, 'Drywall Repair in Essex, Morris, Bergen & Union NJ from $349', 'Reparación de drywall en Essex, Morris, Bergen y Union, $349', 'Drywall repair costs from $349 for the first patch in Essex, Morris, Bergen and Union NJ: patched, taped, primed and painted to blend. Firm price.', 'Reparación de drywall desde $349 por el primer parche en Essex, Morris, Bergen y Union NJ: parchado, encintado, imprimado y pintado. Precio firme.', '["drywall repair NJ","how much does drywall repair cost","drywall repair near me","drywall patching Essex County","drywall repair Morris County","drywall contractor Bergen County","drywall repair Union County"]'::jsonb, '[{"q":{"en":"How much does drywall repair cost in NJ?","es":"¿Cuánto cuesta la reparación de drywall en NJ?"},"a":{"en":"From $349 for the first patch up to 6 inches, taped, skimmed, sanded, primed and painted to blend. Each extra patch, large holes, ceilings and paint matching add to it, and you get the firm price from a photo of the damage.","es":"Desde $349 por el primer parche de hasta 6 pulgadas, encintado, enmasillado, lijado, imprimado y pintado. Cada parche extra, hoyos grandes, techos e igualar la pintura suben el precio, y recibe el precio firme con una foto del daño."}},{"q":{"en":"Will the patch be invisible?","es":"¿Se notará el parche?"},"a":{"en":"On a flat wall with matched paint, yes. Heavy texture and old faded paint can leave a faint difference, which we tell you before starting.","es":"En una pared lisa con pintura igualada, no se nota. Texturas gruesas y pintura vieja pueden dejar una ligera diferencia; se lo decimos antes de empezar."}},{"q":{"en":"How long does it take?","es":"¿Cuánto tarda?"},"a":{"en":"Two visits a day apart for most patches: one to patch and skim, one to sand, prime and paint once it has dried.","es":"Dos visitas con un día de diferencia en la mayoría de los parches: una para parchar y enmasillar, otra para lijar, imprimar y pintar cuando haya secado."}},{"q":{"en":"Can I add other services to the same request?","es":"¿Puedo agregar otros servicios a la misma solicitud?"},"a":{"en":"Yes. Tick cabinet repainting or a home cleaning, or anything else on the list, and send one request. You get one firm price, one schedule and one point of contact; the crews come in order while you sit back.","es":"Sí. Marque repintado de gabinetes o limpieza de casa, o cualquier otro servicio de la lista, y envíe una sola solicitud. Recibe un solo precio firme, una sola agenda y un solo contacto; los equipos llegan en orden mientras usted se relaja."}}]'::jsonb)
ON CONFLICT (slug) DO NOTHING;

-- 2. blog_posts (guarded) ---------------------------------------------------

DO $$
BEGIN
  IF to_regclass('public.blog_posts') IS NOT NULL THEN
    ALTER TABLE public.blog_posts ADD COLUMN IF NOT EXISTS published_at timestamptz;
    ALTER TABLE public.blog_posts ADD COLUMN IF NOT EXISTS faq jsonb;
    ALTER TABLE public.blog_posts ADD COLUMN IF NOT EXISTS review_hold jsonb;
    ALTER TABLE public.blog_posts ADD COLUMN IF NOT EXISTS source text NOT NULL DEFAULT 'admin';
    -- Backfill: a post that is live today was published when it was created.
    -- The preview baseline stub of blog_posts has no created_at, so guard it.
    IF EXISTS (SELECT 1 FROM information_schema.columns
               WHERE table_schema = 'public' AND table_name = 'blog_posts' AND column_name = 'created_at') THEN
      EXECUTE 'UPDATE public.blog_posts SET published_at = created_at
                 WHERE published_at IS NULL AND published = true AND created_at IS NOT NULL';
    END IF;
  END IF;
END $$;

-- 3. experiments ------------------------------------------------------------

CREATE TABLE IF NOT EXISTS public.experiments (
  key text PRIMARY KEY,
  page text NOT NULL,
  element text NOT NULL,
  hypothesis text NOT NULL,
  variants jsonb NOT NULL,
  control_key text NOT NULL DEFAULT 'A',
  status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'running', 'pending_promotion', 'concluded', 'retired')),
  primary_metric text NOT NULL DEFAULT 'request_submitted',
  min_visitors integer NOT NULL DEFAULT 200,
  min_days integer NOT NULL DEFAULT 14,
  started_at timestamptz,
  concluded_at timestamptz,
  winner_key text,
  decision jsonb,
  created_by text NOT NULL DEFAULT 'admin',
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.experiments ENABLE ROW LEVEL SECURITY;
-- One running experiment per page (slice H guardrail).
CREATE UNIQUE INDEX IF NOT EXISTS experiments_one_running_per_page
  ON public.experiments (page) WHERE status IN ('running', 'pending_promotion');

CREATE TABLE IF NOT EXISTS public.experiment_events (
  id bigserial PRIMARY KEY,
  experiment_key text NOT NULL REFERENCES public.experiments(key) ON DELETE CASCADE,
  variant_key text NOT NULL,
  visitor_id uuid NOT NULL,
  event text NOT NULL CHECK (event IN ('view', 'click', 'request_started', 'request_submitted', 'quote_accepted', 'job_paid')),
  value_cents integer,
  created_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.experiment_events ENABLE ROW LEVEL SECURITY;
CREATE UNIQUE INDEX IF NOT EXISTS experiment_events_once_per_visitor
  ON public.experiment_events (experiment_key, variant_key, visitor_id, event);
CREATE INDEX IF NOT EXISTS experiment_events_report_idx
  ON public.experiment_events (experiment_key, variant_key, event);

CREATE TABLE IF NOT EXISTS public.experiment_backlog (
  id bigserial PRIMARY KEY,
  page text NOT NULL,
  element text NOT NULL,
  hypothesis text NOT NULL,
  priority integer NOT NULL DEFAULT 50,
  source text NOT NULL DEFAULT 'planner',
  status text NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'started', 'dropped')),
  created_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.experiment_backlog ENABLE ROW LEVEL SECURITY;

